import{_ as d,a as t,b as o}from"./chunks/5elements-2.75774190.js";import{D as c}from"./chunks/donate.3a95be8c.js";import{o as a,c as r,O as l,X as e}from"./chunks/framework.7fab6bae.js";import"./chunks/wcpay.d0e1a780.js";const i=e('<h1 id="紫微斗数基础" tabindex="-1">紫微斗数の基礎 <a class="header-anchor" href="#紫微斗数基础" aria-label="Permalink to &quot;紫微斗数の基礎  {#紫微斗数基础}&quot;">​</a></h1><h2 id="前言" tabindex="-1">はじめに <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;はじめに  {#前言}&quot;">​</a></h2><p>紫微斗数は<code>人</code>と<code>外部環境</code>の関係を考える学問です。本サイトのアプローチは、伝統的な学び方と異なる場合があります。すでに学んだ方は、これまでの知識と食い違う説明もあるため、ご自身の理解と照らし合わせて慎重に読んでください。主に初心者向けにしくみを分かりやすく紹介し、その面白さを知ってもらうことを目指しています。誤りがあればご指摘ください。</p><blockquote><p><em>このシリーズの記事はオリジナルです。転載の際は出典を明記してください。</em></p></blockquote><div class="tip custom-block"><p class="custom-block-title">ヒント</p><p>本サイトは論理的な推論を中心に説明します。神秘的な解釈を好む方は、その違いを踏まえてお読みください。</p></div>',5),p=e('<h2 id="紫微斗数能干嘛" tabindex="-1">紫微斗数は何ができるでしょうか？ <a class="header-anchor" href="#紫微斗数能干嘛" aria-label="Permalink to &quot;紫微斗数は何ができるでしょうか？  {#紫微斗数能干嘛}&quot;">​</a></h2><p>多くの方は紫微斗数を、古代中国の運命を占う術としてだけ知っているかもしれません。ただ、私の考えでは、それは娯楽としての機能で、全体ではありません。専門の実践者の方にも、力を否定しているわけではないとご理解いただければと思います。占いの意味を知らないまま、未知への恐れや不安から超自然的な助けを求める人もいます。この章からは、より全体的に紹介します。では、紫微斗数で何ができるのでしょうか。</p><ul><li><p>性格の推論</p><p>命理学や心理学のさまざまな手法は、MBTIのような質問形式の分析も含め、人の性格を考えます。性格は単純で一面的なものではなく、相手や場面によって大きく違う姿を見せます。そのため、単純な分類だけでは説明しきれません。紫微斗数は12の<a href="./palace.html"><code>宮位</code></a>を使い、さまざまな面を分析、分類することで、細かな性格の特徴を読み取ります。</p><p>性格の推論が実際の性格とかけ離れている場合は、そこで止めてください。最初の段階が合ってこそ、その後の解釈にも意味があります。食い違いの原因として、次のことが考えられます。</p><ol><li><p>出生時刻の情報の誤り</p><p>出生時刻は、親の記憶が正確でない場合もあるため、誤りの起こりやすい情報です。1つの時辰は現在の2時間に当たります。3時ごろなど境界に近い場合は2つの命盤が考えられるため、両方を見て、実際の性格にどちらが合うかを比べるとよいでしょう。</p><p>記録された出生時刻に誤りがある場合もあります。例えば、実際には2時54分に生まれたのに3時5分と記録されると、出生時辰が変わってしまいます。</p><p>暦の変換や区切り方の違いによって、命盤が変わることもあります。紫微斗数で用いる中国の農暦は、それ自体が太陰太陽暦です。月は月の満ち欠けに従い、節気は太陽の季節的な動きを示します。そのため、農暦の月の区切りと、一部の干支計算で用いる節気の区切りは区別する必要があります。節入りの時刻も、必ずしも午前零時ではありません。境界付近に生まれた場合は、日付の変換と適用する排盤規則を確認したうえで、候補となる命盤を比較してください。</p><p>サマータイムなどの時計の調整で、出生時辰がずれる場合もあります。以下は中国本土でサマータイムが実施された期間です。この期間に生まれた場合は、記録時刻から1時間引きます。ただし、親がすでに補正していることもあるため、先に確認してください。詳しくは<a href="https://baike.baidu.com/item/%E5%A4%8F%E4%BB%A4%E6%97%B6/1809579" target="_blank" rel="noreferrer"><code>百度百科事典</code></a>を参照してください。</p><table><thead><tr><th>中国本土の夏時間</th></tr></thead><tbody><tr><td>1986年5月4日～9月14日（1986年は夏時間開始年のため、5月4日開始、9月14日終了）</td></tr><tr><td>1987年4月12日から9月13日まで</td></tr><tr><td>1988年4月10日から9月11日まで</td></tr><tr><td>1989年4月16日から9月17日まで</td></tr><tr><td>1990年4月15日から9月16日まで</td></tr><tr><td>1991年4月14日から9月15日まで</td></tr></tbody></table><p>他の国または地域における夏時間の実施時間については、現地の公式データを参照してください。</p></li><li><p>命盤を読む人の紫微斗数の習熟度</p><p>読む人によって習熟度が異なるため、逆の結論になることもあります。出生時刻が正しいと分かっていれば、こうした食い違いに気付きやすくなります。対面で相手の表情や反応を見て誘導する言葉に頼る場合は、自分の力不足を認めたくないのかもしれません。私自身の実力も普通ですが、うまく分析できなかった場合は率直に受け止めます。一度不正確だったからといって、紫微斗数全体への信頼を失わないでほしいと思います。アルゴリズムや文書を公開したのも、誰もが基礎を持ち、興味があれば詳しく研究できるようにするためです。</p></li><li><p>命盤を読む人の伝え方</p><p>伝え方や理解の仕方も、食い違いの原因になります。同じ『ハムレット』でも読む人によって解釈が違い、作者がカーテンを青く描いた理由の読み方もさまざまです。同じように、命盤を読む人が伝えたいことと、持ち主が受け取る意味にも差が生まれます。</p></li></ol></li><li><p>子どもの教育</p><p>親は「自分の子どものことは分かっている」と思いがちです。しかし見えているのは性格の一面です。24時間一緒にいて、同級生や友人とどう接するか、相手の立場によってどんな姿を見せるか、親をどう見ているかまで観察することはできません。筆者は、子どもの命盤からこうした面を知り、その子に合った教育につなげられると考えています。</p></li><li><p>キャリアプランニング</p><p>明確な目標がある人には、あまり役立たないかもしれません。ただ、どんな仕事が向くか、大学でどの専攻を選ぶか迷う人には参考になります。将来の仕事で順調な時期や困難な時期を予報のように考え、前もって備えることもできます。</p></li><li><p>会話のきっかけ</p><p>星座やMBTIと同じく、紫微斗数も会話のきっかけになります。初対面の緊張をほぐし、早く知り合う助けになり、双方がある程度知っていれば特に話が進みやすくなります。</p></li><li><p>結婚相手を選ぶこと</p><p>結婚相手選びというと、出生情報を使った相性占いを思い浮かべるかもしれませんが、ここでいう使い方は違います。お見合いでも自然な恋愛でも、正確な生年月日や出生時刻をいきなり聞くのは気まずいものです。紫微斗数を知っていれば、会話や接し方から星曜の組み合わせを大まかに考え、付き合い方の参考にできます。双方が知っていれば、星座のように主星を話題にし、出生情報を聞かずに性格や好みを素早く知る助けになります。</p></li></ul><h2 id="术语解释" tabindex="-1">用語説明 <a class="header-anchor" href="#术语解释" aria-label="Permalink to &quot;用語説明  {#术语解释}&quot;">​</a></h2><p>紫微斗数には専門用語が多く、意味を知ると人の命盤の解釈も理解しやすくなります。多くの解釈に触れたら、自分でも読んでみましょう。命盤を研究する楽しさを感じられるよう、よく使う用語を順に説明します。</p><h3 id="性别阴阳" tabindex="-1"><code>性別の陰と陽</code> <a class="header-anchor" href="#性别阴阳" aria-label="Permalink to &quot;`性別の陰と陽`  {#性别阴阳}&quot;">​</a></h3><p>紫微斗数では <code>陽男陰女</code> と <code>陰男陽女</code> という表現をよく使います。出生年の <code>天干</code> の陰陽と性別を組み合わせると、次の四つに分かれます。</p><ul><li>陽年生まれの男性</li><li>陽年生まれの女性</li><li>陰年生まれの男性</li><li>陰年生まれの女性</li></ul><p>性別と出生年の陰陽は、一部の計算の進行方向に影響します。</p><h3 id="顺行-逆行" tabindex="-1"><code>順行</code>/<code>逆行</code> <a class="header-anchor" href="#顺行-逆行" aria-label="Permalink to &quot;`順行`/`逆行`  {#顺行-逆行}&quot;">​</a></h3><p>紫微斗数で順行とは<code>時計回り</code>に、逆行や逆部とは<code>反時計回り</code>に進むことです。<code>陽男陰女順行</code>は<code>時計回り</code>の配列を、<code>陰男陽女逆行（逆部）</code>は<code>反時計回り</code>の配列を意味します。</p><h3 id="星盘" tabindex="-1"><code>命盤</code> <a class="header-anchor" href="#星盘" aria-label="Permalink to &quot;`命盤`  {#星盘}&quot;">​</a></h3><p>詳しくは<a href="./astrolabe.html">命盤の紹介</a>を参照してください。</p><ul><li><p>命盤の作成</p><p>出生年月日、時辰、性別から命盤を作成することです。</p></li><li><p>命盤の解釈</p><p>命盤に示された情報を読み解くことです。</p></li><li><p>本命盤</p><p><code>天盤</code> とも呼ばれ、出生年月日と時辰から算出する命盤です。その配置は固定されています。</p></li><li><p>大限盤</p><p><code>地盤</code> とも呼びます。天盤の十二宮が順に中心となり、各宮の期間は <code>10年</code> です。<code>命宮</code> が <code>第一大限</code> となり、その後を <code>第n大限</code> と呼びます。</p></li><li><p>流年盤</p><p><code>人盤</code> とも呼びます。大限が十年ごとに変わるのに対し、流年は <code>毎年</code> 変わります。その年の <code>地支</code> に対応する宮が流年命宮になります。</p></li><li><p>天地人の三才</p><p><code>本命盤</code>、<code>大限盤</code>、<code>流年盤</code>の総称です。</p></li><li><p>格局</p><p>特定の<code>星曜</code>の組み合わせは<code>格局</code>を作ります。ゲームの装備の<code>セット効果</code>のように、特定の性質に追加の作用を与えます。</p></li></ul><h3 id="宫位" tabindex="-1"><code>宮位</code> <a class="header-anchor" href="#宫位" aria-label="Permalink to &quot;`宮位`  {#宫位}&quot;">​</a></h3><p>宮位の基本知識は<a href="./palace.html">宮位のしくみ</a>で詳しく説明します。</p><ul><li><p>宮干</p><p>その宮の<code>天干</code>を指します。</p></li><li><p>対象の宮</p><p>今調べている宮です。<code>夫妻</code>宮を見ているなら、その宮が<code>対象の宮</code>になります。</p></li><li><p>対宮</p><p>対象の宮の向かい側にある宮で、<code>対宮の位置</code>とも呼びます。</p></li><li><p>三合の位置</p><p><code>三才方</code>や<code>三方</code>とも呼び、<code>対象の宮</code>と、その番号に<code>±4</code>を適用した2つの宮を合わせて指します。</p></li><li><p>対宮の位置</p><p><code>対宮</code>とも呼ばれ、<code>対象の宮</code>のインデックスに<code>+6</code>を適用した位置です。</p></li><li><p>三方四正</p><p><code>三合の位置</code>と<code>対宮の位置</code>の総称です。</p></li><li><p>天羅・地網</p><p><code>辰</code>と<code>戌</code>の2つの宮を指し、<code>辰</code>が天羅の位置、<code>戌</code>が地網の位置です。『周易』に由来する概念で、辰は<code>天罡</code>、戌は<code>河魁</code>に対応します。この2つは大六壬の十二神将にも含まれます。覚える必要はありませんが、興味があれば詳しく調べてみてください。</p></li><li><p>空宮</p><p>その宮に<a href="./major-star.html">主星</a>がないことです。</p></li><li><p>両隣の宮</p><p>対象の宮のすぐ前後にある2つの宮です。</p></li><li><p>天門・地門</p><p>これらの概念は風水から来ています。</p><p>天門は <code>亥の宮</code> を指します。後天八卦では乾卦の位置に当たり、地支では <code>戌</code> と <code>亥</code> に対応します。ただし戌の宮にはすでに <code>地網の位置</code> の意味があるため、天門は <code>亥の宮</code> に対応させます。<code>月朗天門</code> という格局は、命宮または身宮が亥の宮にあり、そこに <code>太陰</code> がある配置です。</p><p>地門は <code>巳の宮</code> を指し、風水では <code>地戸の位置</code>、すなわち <code>地に入る門</code> です。地支では <code>辰</code> と <code>巳</code> に対応しますが、辰の宮にはすでに <code>天羅の位置</code> の意味があるため、地門は <code>巳の宮</code> に対応させます。</p></li><li><p>雷門</p><p><code>卯の宮</code> を指します。卯の宮は八卦の <code>震卦</code> の位置に当たるため、<code>雷門</code> と呼びます。<code>日照雷門</code> とは、<code>太陽</code> と <code>天梁</code> が卯の宮に同宮する配置です。</p></li><li><p>天宮・地宮</p><p>天宮は <code>子の宮</code>、地宮は <code>丑の宮</code> を指します。「天開於子，地闢於丑，人生於寅」という考え方で、来因宮の説明に関係します。<code>天宮</code>・<code>地宮</code> を、先述の <code>天門</code>・<code>地門</code> と混同しないでください。名称は似ていますが、由来も位置も異なる概念です。</p></li></ul><h3 id="星曜" tabindex="-1"><code>星曜</code> <a class="header-anchor" href="#星曜" aria-label="Permalink to &quot;`星曜`  {#星曜}&quot;">​</a></h3><p>星曜は、紫微斗数の宮位を構成する重要な要素です。詳しくは<a href="./star.html">星曜のしくみ</a>を参照してください。</p><ul><li><p>流曜</p><p><code>大限</code>や<code>流年</code>に応じて変わる星曜です。</p></li><li><p>遇・加・逢・同宮・同度</p><p>星曜が同じ宮にあることです。例えば<code>紫微</code>と<code>右弼</code>が同度とは、両方が同じ宮にあるという意味です。</p></li><li><p>会・照・冲・扶拱</p><p><code>会</code>と<code>扶拱</code>は、星曜が対象の宮の<code>三方の位置</code>にあることです。<code>照</code>と<code>冲</code>は、<code>対宮の位置</code>にあることです。ある星曜と「会照する」と言う場合は、その星曜が<code>三方四正</code>の範囲にあれば該当します。</p></li><li><p>坐・據・守</p><p>星曜がある宮に入っていることです。例えば<code>貪狼</code>が<code>夫妻</code>宮に坐すとは、その宮にあるという意味です。</p></li><li><p>空星・空曜</p><p><code>地空</code>、<code>天空</code>、<code>旬空</code>、<code>空亡</code>を指します。</p></li><li><p>暗曜</p><p><a href="./major-star.html#巨门星"><code>巨門</code></a>を指します</p></li><li><p>英星</p><p><a href="./major-star.html#破军星"><code>破軍</code></a>を指します</p></li><li><p>将星</p><p><a href="./major-star.html#七杀星"><code>七殺</code></a>を指します</p></li></ul><h2 id="阴阳五行" tabindex="-1">陰陽と五行 <a class="header-anchor" href="#阴阳五行" aria-label="Permalink to &quot;陰陽と五行  {#阴阳五行}&quot;">​</a></h2><p>中国の道家思想では<code>陰陽</code>と<code>五行</code>が根本的な概念です。ここでは詳しく扱わず、概要だけを紹介します。</p><ul><li><p>陰陽</p><p>道家で「一から二が生じる」と言うとき、その二とは陰陽であり、物事の二つの側面を表します。たとえば、</p><ul><li><code>光</code>は<code>陽</code>、<code>影</code>は<code>陰</code>です。</li><li><code>男性</code>は<code>陽</code>、<code>女性</code>は<code>陰</code>です。</li><li><code>正電荷</code> は <code>陽</code>、<code>マイナス電荷</code> は <code>陰</code> となります。</li></ul><p>このように、陰陽は相対的な概念です。万物は互いに補い合い、幸と不幸もつながっています。大切なのは、過不足を避けて陰陽のバランスを取ることです。<code>陽</code>は力強さや激しさを、<code>陰</code>は柔らかさや控えめな性質を連想させます。</p></li><li><p>五行</p><p><code>元素</code>の考え方は文化によって異なります。例えば古代ギリシャでは、<code>土</code>・<code>風</code>・<code>水</code>・<code>火</code>の4つでした。</p><img src="'+d+'" alt="four elements" width="300"><p>古代インドの <code>五元素</code> は、古代ギリシャの四元素に <code>空間</code> を加えたものです。<code>土</code>・<code>風</code>・<code>水</code>・<code>火</code>・<code>空間</code> からなります。</p><img src="'+t+'" alt="five elements" width="300"><p>中国の<code>五行</code>は、他の元素の体系と共通する部分も異なる部分もあります。<code>五行</code>は<code>水</code>・<code>木</code>・<code>金</code>・<code>土</code>・<code>火</code>です。金・木・水・火・土の順のほうが言いやすいかもしれませんが、ここでは紫微斗数の<a href="#五行局">五行局</a>に合わせて並べています。</p><img src="'+o+'" alt="five elements" width="300"></li></ul><h2 id="天干地支" tabindex="-1">天干と地支 <a class="header-anchor" href="#天干地支" aria-label="Permalink to &quot;天干と地支  {#天干地支}&quot;">​</a></h2><p>中国の伝統文化において、<code>干支紀年</code> は、数学における足し算、引き算、掛け算、割り算、英語の 26 文字と同じように、非常に重要な基礎知識です。 紫微斗数 では、<code>天干</code> と <code>地支</code> に従って命盤全体の配置が計算されます。したがって、基礎として暗記する必要があります。</p><h3 id="十天干" tabindex="-1">十天干 <a class="header-anchor" href="#十天干" aria-label="Permalink to &quot;十天干  {#十天干}&quot;">​</a></h3><p>十天干は、紫微斗数で重要かつ有用な<code>四化</code>を定めます。詳しくは<a href="./mutagen.html">四化星</a>を参照してください。</p><table><thead><tr><th>名称</th><th>五行</th><th>陰陽</th></tr></thead><tbody><tr><td>甲</td><td>🪵 木</td><td>🌕 陽</td></tr><tr><td>乙</td><td>🪵 木</td><td>🌑 陰</td></tr><tr><td>丙</td><td>🔥 火</td><td>🌕 陽</td></tr><tr><td>丁</td><td>🔥 火</td><td>🌑 陰</td></tr><tr><td>戊</td><td>⛰️ 土</td><td>🌕 陽</td></tr><tr><td>己</td><td>⛰️ 土</td><td>🌑 陰</td></tr><tr><td>庚</td><td>🪙 金</td><td>🌕 陽</td></tr><tr><td>辛</td><td>🪙 金</td><td>🌑 陰</td></tr><tr><td>壬</td><td>🌊 水</td><td>🌕 陽</td></tr><tr><td>癸</td><td>🌊 水</td><td>🌑 陰</td></tr></tbody></table><h3 id="十二地支" tabindex="-1">十二地支 <a class="header-anchor" href="#十二地支" aria-label="Permalink to &quot;十二地支  {#十二地支}&quot;">​</a></h3><p>地支は、紫微斗数の宮位の固定した位置を定めます。学校を建てると各学年や教室の場所が決まるようなものです。一方、<code>命宮</code>の位置は人によって異なり、入学時に1組にも10組にも配属されることにたとえられます。十二宮での地支の位置は下の表を参照してください。</p><table class="astrolabe"><tr><td>巳<code>3</code></td><td>午<code>4</code></td><td>未<code>5</code></td><td>申<code>6</code></td></tr><tr><td>辰<code>2</code></td><td class="center-palace" rowspan="2" colspan="2">中宮</td><td>酉<code>7</code></td></tr><tr><td>卯<code>1</code></td><td>戌<code>8</code></td></tr><tr><td>寅<code>0</code></td><td>丑<code>11</code></td><td>子<code>10</code></td><td>亥<code>9</code></td></tr></table><p>天干と同じく、十二地支にも陰陽と五行の区分があります。</p><table><thead><tr><th>名称</th><th>五行</th><th>陰陽</th></tr></thead><tbody><tr><td>子</td><td>🌊 水</td><td>🌕 陽</td></tr><tr><td>丑</td><td>⛰️ 土</td><td>🌑 陰</td></tr><tr><td>寅</td><td>🪵 木</td><td>🌕 陽</td></tr><tr><td>卯</td><td>🪵 木</td><td>🌑 陰</td></tr><tr><td>辰</td><td>⛰️ 土</td><td>🌕 陽</td></tr><tr><td>巳</td><td>🔥 火</td><td>🌑 陰</td></tr><tr><td>午</td><td>🔥 火</td><td>🌕 陽</td></tr><tr><td>未</td><td>⛰️ 土</td><td>🌑 陰</td></tr><tr><td>申</td><td>🪙 金</td><td>🌕 陽</td></tr><tr><td>酉</td><td>🪙 金</td><td>🌑 陰</td></tr><tr><td>戌</td><td>⛰️ 土</td><td>🌕 陽</td></tr><tr><td>亥</td><td>🌊 水</td><td>🌑 陰</td></tr></tbody></table><h4 id="地支六合" tabindex="-1">地支六合 <a class="header-anchor" href="#地支六合" aria-label="Permalink to &quot;地支六合  {#地支六合}&quot;">​</a></h4><p><code>結合</code>には<code>相互の助け</code>という意味があり、その助けは<code>密かに</code>行われます。ここでは地支を詳しく論じず、<a href="./palace.html#暗合宫">暗合宮</a>の説明に必要な六合を示します。</p><ul><li><code>子</code>と<code>丑</code>が結合し、<code>⛰️土</code>となります。</li><li><code>寅</code>と<code>亥</code>が結合し、<code>🪵木</code>となります。</li><li><code>卯</code>と<code>戌</code>が結合し、<code>🔥火</code>となります。</li><li><code>辰</code>と<code>酉</code>が結合し、<code>🪙金</code>となります。</li><li><code>巳</code>と<code>申</code>が結合し、<code>🌊水</code>となります。</li><li><code>午</code>と<code>未</code>が結合し、<code>⛰️土</code>となります。</li></ul><h4 id="地支三合局" tabindex="-1">地支三合局 <a class="header-anchor" href="#地支三合局" aria-label="Permalink to &quot;地支三合局  {#地支三合局}&quot;">​</a></h4><p>六合と同じく、三合の<code>結合</code>も助け合う関係です。ただし六合が<code>密かに</code>助けるのに対し、三合は表立って助けます。ここでは<a href="./palace.html#三方四正">三方四正</a>の説明に必要な地支の三合局を紹介します。</p><ul><li><code>申</code>・<code>子</code>・<code>辰</code>が結合し、<code>🌊水</code>の局となります。</li><li><code>亥</code>・<code>卯</code>・<code>未</code>が結合し、<code>🪵木</code>の局となります。</li><li><code>寅</code>・<code>午</code>・<code>戌</code>が結合し、<code>🔥火</code>の局となります。</li><li><code>巳</code>・<code>酉</code>・<code>丑</code>が結合し、<code>🪙金</code>の局となります。</li></ul><h4 id="地支六冲" tabindex="-1">地支六冲 <a class="header-anchor" href="#地支六冲" aria-label="Permalink to &quot;地支六冲  {#地支六冲}&quot;">​</a></h4><p><code>冲</code>は対立を表し、調和させるには大きな力が必要な関係です。地支の六冲は<a href="./palace.html#三方四正">三方四正</a>の説明に使います。</p><ul><li><code>子</code>と<code>午</code>は互いに冲します。</li><li><code>卯</code>と<code>酉</code>は互いに冲します。</li><li><code>寅</code>と<code>申</code>は互いに冲します。</li><li><code>巳</code>と<code>亥</code>は互いに冲します。</li><li><code>辰</code>と<code>戌</code>は互いに冲します。</li><li><code>丑</code>と<code>未</code>は互いに冲します。</li></ul><h2 id="十二时辰" tabindex="-1">十二時辰 <a class="header-anchor" href="#十二时辰" aria-label="Permalink to &quot;十二時辰  {#十二时辰}&quot;">​</a></h2><p>中国の伝統的な時刻では、1日を<code>十二時辰</code>に分け、1時辰は現在の2時間に当たります。<code>子時</code>は<code>23:00~01:00</code>で日付をまたぐため、特別に<code>早子時</code>と<code>晩子時</code>に分けます。対応する時刻は次の表のとおりです。</p><table><thead><tr><th>名称</th><th>時間帯</th></tr></thead><tbody><tr><td>早子時</td><td>00:00～01:00</td></tr><tr><td>丑時</td><td>01:00～03:00</td></tr><tr><td>寅時</td><td>03:00～05:00</td></tr><tr><td>卯時</td><td>05:00～07:00</td></tr><tr><td>辰時</td><td>07:00～09:00</td></tr><tr><td>巳時</td><td>09:00～11:00</td></tr><tr><td>午時</td><td>11:00～13:00</td></tr><tr><td>未時</td><td>13:00～15:00</td></tr><tr><td>申時</td><td>15:00～17:00</td></tr><tr><td>酉時</td><td>17:00～19:00</td></tr><tr><td>戌時</td><td>19:00～21:00</td></tr><tr><td>亥時</td><td>21:00～23:00</td></tr><tr><td>晩子時</td><td>23:00～00:00</td></tr></tbody></table><h2 id="五行局" tabindex="-1">五行局 <a class="header-anchor" href="#五行局" aria-label="Permalink to &quot;五行局  {#五行局}&quot;">​</a></h2><p>五行局は、紫微斗数の最初の大限が始まる年齢を決める基準です。<code>六十干支の納音</code>に由来しますが、本サイトでは<code>六十納音</code>自体は扱わないため、興味があれば別に学んでください。名称の数字が開始年齢を示し、水の二局なら<code>2</code>歳、土の五局なら<code>5</code>歳から始まります。ここではその理解で十分です。五行局は次の5種類です。</p><ul><li>🌊 <code>水の二局</code></li><li>🪵 <code>木の三局</code></li><li>🪙 <code>金の四局</code></li><li>⛰️ <code>土の五局</code></li><li>🔥 <code>火の六局</code></li></ul>',48),g=JSON.parse('{"title":"紫微斗数入門：基礎知識と用語","description":"紫微斗数とは何かを紹介し、命盤を読むための基礎知識や用語を解説します。","frontmatter":{"title":"紫微斗数入門：基礎知識と用語","outline":"deep","description":"紫微斗数とは何かを紹介し、命盤を読むための基礎知識や用語を解説します。","head":[["link",{"rel":"canonical","href":"https://iztro.com/ja_JP/learn/basis.html"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://iztro.com/learn/basis.html"}],["link",{"rel":"alternate","hreflang":"zh-TW","href":"https://iztro.com/zh_TW/learn/basis.html"}],["link",{"rel":"alternate","hreflang":"en-US","href":"https://iztro.com/en_US/learn/basis.html"}],["link",{"rel":"alternate","hreflang":"ko-KR","href":"https://iztro.com/ko_KR/learn/basis.html"}],["link",{"rel":"alternate","hreflang":"ja-JP","href":"https://iztro.com/ja_JP/learn/basis.html"}],["link",{"rel":"alternate","hreflang":"vi-VN","href":"https://iztro.com/vi_VN/learn/basis.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://iztro.com/learn/basis.html"}],["meta",{"name":"robots","content":"max-image-preview:large"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"紫微研习社"}],["meta",{"property":"og:title","content":"紫微斗数入門：基礎知識と用語 | 紫微研习社"}],["meta",{"property":"og:description","content":"紫微斗数とは何かを紹介し、命盤を読むための基礎知識や用語を解説します。"}],["meta",{"property":"og:url","content":"https://iztro.com/ja_JP/learn/basis.html"}],["meta",{"property":"og:locale","content":"ja_JP"}],["meta",{"property":"og:locale:alternate","content":"zh_CN"}],["meta",{"property":"og:locale:alternate","content":"zh_TW"}],["meta",{"property":"og:locale:alternate","content":"en_US"}],["meta",{"property":"og:locale:alternate","content":"ko_KR"}],["meta",{"property":"og:locale:alternate","content":"vi_VN"}],["meta",{"property":"og:image","content":"https://iztro.com/static/home_img.png"}],["meta",{"property":"og:image:width","content":"850"}],["meta",{"property":"og:image:height","content":"850"}],["meta",{"property":"og:image:alt","content":"紫微研习社"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"紫微斗数入門：基礎知識と用語 | 紫微研习社"}],["meta",{"name":"twitter:description","content":"紫微斗数とは何かを紹介し、命盤を読むための基礎知識や用語を解説します。"}],["meta",{"name":"twitter:image","content":"https://iztro.com/static/home_img.png"}],["meta",{"name":"twitter:image:alt","content":"紫微研习社"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://iztro.com/ja_JP/learn/basis.html#webpage\\",\\"url\\":\\"https://iztro.com/ja_JP/learn/basis.html\\",\\"name\\":\\"紫微斗数入門：基礎知識と用語 | 紫微研习社\\",\\"description\\":\\"紫微斗数とは何かを紹介し、命盤を読むための基礎知識や用語を解説します。\\",\\"inLanguage\\":\\"ja-JP\\",\\"isPartOf\\":{\\"@id\\":\\"https://iztro.com/#website\\"},\\"breadcrumb\\":{\\"@id\\":\\"https://iztro.com/ja_JP/learn/basis.html#breadcrumb\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"@id\\":\\"https://iztro.com/ja_JP/learn/basis.html#breadcrumb\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"紫微研习社\\",\\"item\\":\\"https://iztro.com/ja_JP/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"紫微斗数入門：基礎知識と用語\\",\\"item\\":\\"https://iztro.com/ja_JP/learn/basis.html\\"}]}]}"]]},"headers":[],"relativePath":"ja_JP/learn/basis.md","filePath":"ja_JP/learn/basis.md"}'),h={name:"ja_JP/learn/basis.md"},P=Object.assign(h,{setup(n){return(s,m)=>(a(),r("div",null,[i,l(c),p]))}});export{g as __pageData,P as default};
